public static ItemStack readItemStack(JsonArray array) {
		try {
			Item item = (Item) Item.itemRegistry.getObject(array.get(0).getAsString());
			int stacksize = array.size() > 1 ? array.get(1).getAsInt() : 1;
			int meta = array.size() > 2 ? array.get(2).getAsInt() : 0;
			if(item != null) {
				ItemStack stack = new ItemStack(item, stacksize, meta);
				if(array.size() > 3) ItemStackUtil.addNBTFromString(stack, array.get(3).getAsString());
				return stack;
			}
		} catch(Exception ex) { }
		MainRegistry.logger.error("Error reading stack array " + array.toString() + " - defaulting to NOTHING item!");
		return new ItemStack(ModItems.nothing);
	}

public static void addRecipe(Object in1, Object in2, ItemStack out) {

		if(in1 instanceof Item) in1 = new ComparableStack((Item) in1);
		if(in1 instanceof Block) in1 = new ComparableStack((Block) in1);
		if(in2 instanceof Item) in2 = new ComparableStack((Item) in2);
		if(in2 instanceof Block) in2 = new ComparableStack((Block) in2);

		blastFurnaceRecipes.add(new Triplet<Object, Object, ItemStack>(in1, in2, out));
	}

public static ItemStack getOutput(ItemStack in1, ItemStack in2) {
		for(Triplet<Object, Object, ItemStack> recipe : blastFurnaceRecipes) {
			AStack[] recipeItem1 = getRecipeStacks(recipe.getX());
			AStack[] recipeItem2 = getRecipeStacks(recipe.getY());

			if((doStacksMatch(recipeItem1, in1) && doStacksMatch(recipeItem2, in2)) || (doStacksMatch(recipeItem2, in1) && doStacksMatch(recipeItem1, in2))) {
				return recipe.getZ().copy();
			} else {
				continue;
			}
		}
		return null;
	}

public void readRecipe(JsonElement recipe) {
		JsonObject rec = (JsonObject) recipe;

		ItemStack output = this.readItemStack(rec.get("output").getAsJsonArray());

		Object input1 = null;
		Object input2 = null;

		JsonArray array1 = rec.get("input1").getAsJsonArray();
		if(array1.get(0).getAsString().equals("item")) input1 = this.readAStack(array1);
		if(array1.get(0).getAsString().equals("dict")) input1 = ((OreDictStack) this.readAStack(array1)).name;
		if(array1.get(0).getAsString().equals("dictframe")) input1 = readDictFrame(array1);

		JsonArray array2 = rec.get("input2").getAsJsonArray();
		if(array2.get(0).getAsString().equals("item")) input2 = this.readAStack(array2);
		if(array2.get(0).getAsString().equals("dict")) input2 = ((OreDictStack) this.readAStack(array2)).name;
		if(array2.get(0).getAsString().equals("dictframe")) input2 = readDictFrame(array2);

		if(input1 != null && input2 != null) {
			addRecipe(input1, input2, output);

			if(rec.has("hidden") && rec.get("hidden").getAsBoolean()) {
				this.hiddenRecipes.add(new ComparableStack(output));
			}
		}
	}

public void setInventorySlotContents(int i, ItemStack itemStack) {
		slots[i] = nativeStack(itemStack).isEmpty() ? null : itemStack;
		if(slots[i] != null && itemStack.getCount() > getInventoryStackLimit()) {
			itemStack.setCount(getInventoryStackLimit());
		}
	}

public void readFromNBT(NBTTagCompound nbt) {
		super.readFromNBT(nbt);
		NBTTagList list = nbt.getTagList("items", 10);

		for(int i = 0; i < list.tagCount(); i++)
		{
			NBTTagCompound nbt1 = list.getCompoundTagAt(i);
			byte b0 = nbt1.getByte("slot");
			if(b0 >= 0 && b0 < slots.length)
			{
				ItemStack stack = new ItemStack(nbt1);
				slots[b0] = stack.isEmpty() ? null : stack;
			}
		}

		customName = nbt.getString("name");
	}

public boolean canProcess() {
		if(slots[0] == null || slots[0].isEmpty() || slots[1] == null || slots[1].isEmpty()) return false;
		if(!this.hasPower()) return false;

		ItemStack output = BlastFurnaceRecipes.getOutput(slots[0], slots[1]);
		if(output == null || output.isEmpty()) return false;
		if(slots[3] == null || slots[3].isEmpty()) return true;
		if(!slots[3].isItemEqual(output)) return false;

		if(slots[3].getCount() + output.getCount() <= slots[3].getMaxStackSize()) {
			return true;
		}

		return false;
	}

private int getItemPower(ItemStack stack, boolean canBreathe) {
		if(stack == null || stack.isEmpty()) {
			return 0;
		} else {
			Item item = stack.getItem();

			if(item == Items.COAL) return canBreathe ? 200 : 0;
			if(item == Item.getItemFromBlock(Blocks.COAL_BLOCK)) return canBreathe ? 2000 : 0;
			if(item == Item.getItemFromBlock(ModBlocks.block_coke)) return canBreathe ? 4000 : 0;
			if(item == Items.LAVA_BUCKET) return 12800;
			if(item == Items.BLAZE_ROD) return canBreathe ? 1000 : 0;
			if(item == Items.BLAZE_POWDER) return canBreathe ? 300 : 0;
			if(item == ModItems.lignite) return canBreathe ? 150 : 0;
			if(item == ModItems.powder_lignite) return canBreathe ? 150 : 0;
			if(item == ModItems.powder_coal) return canBreathe ? 200 : 0;
			if(item == ModItems.briquette) return canBreathe ? 200 : 0;
			if(item == ModItems.coke) return canBreathe ? 400 : 0;
			if(item == ModItems.powder_coke) return canBreathe ? 400 : 0;
			if(item == ModItems.solid_fuel) return canBreathe ? 400 : 0;

			return 0;
		}
	}

public boolean canProcess() {
		if(slots[0] == null || slots[1] == null) return false;
		if(!this.hasPower()) return false;

		ItemStack output = BlastFurnaceRecipes.getOutput(slots[0], slots[1]);
		if(output == null) return false;
		if(slots[3] == null) return true;
		if(!slots[3].isItemEqual(output)) return false;

		if(slots[3].stackSize + output.stackSize <= slots[3].getMaxStackSize()) {
			return true;
		}

		return false;
	}

